  "bd.rd.title": "রেডিনেস ম্যাপ", "bd.rd.intro": "প্রতিটি চালু গোলের জন্য: প্রতিটি তথ্য জানা, নেই, পুরোনো, নাকি আপনার নিজের দুটি তারিখ মিলছে না? এখানে কিছুই মাপা বা তুলনা করা হয় না।",
