// Mix mode: Bangla sentences with common English words kept (owner request, decision L-11).
// Keys listed here show English in Mix (they are already English-first in the Bangla pack).
export const COMMON_ENGLISH_KEYS: ReadonlySet<string> = new Set(["badge.demo", "status.online", "status.offline", "label.DEMO", "focus.plus", "focus.minus", "habits.plus", "help.format", "more.theme", "data.demo", "backup.title", "suggest.btn", "habits.of"]);
// Mix mode keeps the English word for everyday words people already say in English (owner rule, 1 Nov 2026).
// Bangla mode writes the same words in Bangla script (for example স্টাফ), so each loanword is listed here with its English form.
// Longer phrases come first. A Bangla suffix after a swapped word is kept after a hyphen, for example Plan-এর.
export const MIX_TERMS: ReadonlyArray<readonly [string, string]> = [
  ["নেট ওয়ার্থ", "Net worth"], ["ওয়ার্কিং ক্যাপিটাল", "Working capital"], ["ক্যাশ ফ্লো", "Cash flow"],
  ["ইমার্জেন্সি ফান্ড", "Emergency fund"], ["ফিক্সড কস্ট", "Fixed cost"], ["ইউনিট ইকোনমিক্স", "Unit economics"],
  ["স্টেজ", "Stage"], ["ধাপ", "Step"], ["যাত্রা", "Journey"], ["ডায়েরি", "Diary"],
  ["ডেমো", "Demo"], ["ব্যাকআপ", "Backup"], ["অনলাইন", "Online"], ["অফলাইন", "Offline"],
  ["প্ল্যান", "Plan"], ["প্রোগ্রেস", "Progress"], ["রিস্ক", "Risk"], ["গোল", "Goal"], ["ডাটা", "Data"], ["নোটিফিকেশন", "Notification"],
  ["অ্যালার্ট", "Alert"], ["অপশনাল", "Optional"], ["পারমিশন", "Permission"], ["লিস্ট", "List"], ["অপশন", "Option"],
  ["স্কিল", "Skill"], ["রেজাল্ট", "Result"], ["ডিলিট", "Delete"], ["ক্যানসেল", "Cancel"], ["সেভ", "Save"],
  ["সেভিংস", "Savings"], ["সেটিংস", "Settings"], ["ভার্সন", "Version"], ["সার্ভিস", "Service"], ["প্রোভাইডার", "Provider"],
  ["সাপ্লায়ার", "Supplier"], ["গ্যারান্টি", "Guarantee"], ["প্রাইভেসি", "Privacy"], ["কানেকশন", "Connection"],
  ["রোল", "Role"], ["ইনকাম", "Income"], ["লোন", "Loan"], ["ক্যাশ", "Cash"], ["ভাইব্রেশন", "Vibration"], ["বাটন", "Button"],
  ["মাইলস্টোন", "Milestone"], ["অ্যাসিস্ট্যান্ট", "Assistant"], ["ল্যাটিচিউড", "Latitude"], ["লংগিচিউড", "Longitude"],
  ["রিভিউয়ার", "Reviewer"], ["রিভিউ", "Review"], ["সামারি", "Summary"], ["শিডিউল", "Schedule"], ["ডেডলাইন", "Deadline"],
  ["পার্সেন্ট", "Percent"], ["স্যাম্পল", "Sample"], ["সোর্স", "Source"], ["রিমাইন্ডার", "Reminder"], ["অটোমেটিক", "Automatic"],
  ["প্রজেক্ট", "Project"], ["কাস্টমার", "Customer"], ["প্রোডাক্ট", "Product"], ["ম্যানেজমেন্ট", "Management"],
  ["প্র্যাকটিস", "Practice"], ["ব্রেক", "Break"], ["কমেন্ট", "Comment"], ["স্টুডেন্ট", "Student"],
  ["সাবস্ক্রিপশন", "Subscription"], ["রিপোর্ট", "Report"], ["স্টাফ", "Staff"], ["টেমপ্লেট", "Template"], ["টার্গেট", "Target"],
  ["ক্যাপিটাল", "Capital"], ["প্রফিট", "Profit"], ["রেভিনিউ", "Revenue"], ["ইকুইটি", "Equity"], ["ভ্যালুয়েশন", "Valuation"],
  ["মেজারেবল", "Measurable"], ["অ্যাচিভেবল", "Achievable"], ["রিলেভেন্ট", "Relevant"], ["স্পেসিফিক", "Specific"], ["ফর্ম", "Form"],
  ["ইনপুট", "Input"], ["আউটপুট", "Output"], ["এক্সপোর্ট", "Export"], ["লিংক", "Link"],
  ["টেস্ট", "Test"], ["রিস্টোর", "Restore"], ["ডার্ক", "Dark"], ["মিউট", "Mute"], ["রিসেট", "Reset"],
];
const MIX_SUFFIX: Record<string, string> = { "ের": "এর", "ে": "এ", "র": "এর", "তে": "তে", "টি": "টি", "টা": "টা", "গুলোর": "গুলোর", "গুলোতে": "গুলোতে", "গুলো": "গুলো", "কে": "কে", "ও": "ও", "ই": "ই", "য়": "এ", "য়": "এ" };
const mixRe = (w: string) => new RegExp(`(?<=^|[\\s(·,।:“"'-])${w}(ের|ে|র|তে|টি|টা|গুলোর|গুলোতে|গুলো|কে|ও|ই|য়|য়)?(?=$|[\\s).,।:!?”"'·-])`, "gu");
// The first terms (up to Offline) are the older ones: they swap whole words only. The loanwords after them also keep a Bangla suffix.
const LEGACY_MIX = 14;
const mixWhole = (w: string) => new RegExp(`(?<=^|[\\s(·,।:“"'-])${w}(?=$|[\\s).,।:!?”"'·])`, "gu");
const MIX_RES = MIX_TERMS.map(([bnWord, enWord], i) => [i < LEGACY_MIX ? mixWhole(bnWord) : mixRe(bnWord), enWord] as const);
export const swapMixTerms = (text: string): string => MIX_RES.reduce((acc, [re, enWord]) => acc.replace(re, (_m, s?: string) => (s ? `${enWord}-${MIX_SUFFIX[s]}` : enWord)), text);
const mix = Object.fromEntries(Object.keys(en).map((k) => [k, COMMON_ENGLISH_KEYS.has(k) ? en[k as Key] : swapMixTerms(bn[k as Key])])) as Record<Key, string>;

export const PACKS: Record<"en" | "bn" | "mix", Record<Key, string>> = { en, bn, mix };
